import {createChatOrchestrator} from './chatOrchestrator.js';
import type {MessageChunk} from '../types/ai.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

const seenByOnError = async (reason: unknown): Promise<Error[]> => {
  const seen: Error[] = [];
  const failing = async function* (): AsyncGenerator<MessageChunk> {
    yield* [];
    throw reason;
  };
  const orchestrator = createChatOrchestrator(
    {sendMessage: failing, generateStructured: async <T>() => ({}) as T},
    new PromptBuilder({identity: 'cause test'}),
    undefined,
    {
      hooks: {
        onError: async (_session, error) => {
          seen.push(error);
        },
      },
    }
  );
  const entries = [{role: 'user' as const, content: 'hi', timestamp: '2026-01-01T00:00:00.000Z'}];
  await orchestrator.processMessage({sessionId: 's', userId: 'u', entries}).catch(() => undefined);
  return seen;
};

describe('ChatOrchestrator onError wrapping', () => {
  it.each([
    ['a string', 'string boom'],
    ['undefined', undefined],
    ['a plain object', {code: 503}],
  ])('wraps %s in one Error whose cause is the original value', async (_label, reason) => {
    const seen = await seenByOnError(reason);

    expect(seen.map(error => ({isError: error instanceof Error, cause: error.cause}))).toEqual([
      {isError: true, cause: reason},
    ]);
  });

  it('passes an Error through as the same instance', async () => {
    const reason = new Error('boom');

    const seen = await seenByOnError(reason);

    expect(seen.map(error => error === reason)).toEqual([true]);
  });
});
EOF
